from html import escape as E

def build_covers(P,css,network,icon,config):
 intro=config['intro_duration'];start=intro+config['body_duration'];outro=config['outro_duration']
 extra='''
.cover-logo{position:absolute;left:192px;top:95px;width:370px;height:90px;object-fit:contain;object-position:left center}.cover-intro .deck-title{top:245px;font-size:96px;line-height:1.26}.cover-intro .deck-lead{top:375px;font-size:38px}.cover-agenda{position:absolute;left:192px;top:535px;display:grid;grid-template-columns:1fr 1fr;gap:44px;width:1536px}.cover-agenda .deck-card{height:116px;background:#182e4f;border-color:#6d8fc4;color:#f8fafc;padding:24px 32px 24px 74px;border-radius:22px 54px 54px 22px}.cover-agenda .deck-card h2{font-size:34px}.cover-agenda .card-icon{top:35px;left:18px;border:0;background:none;padding:4px;width:38px;height:38px}.cover-outro .cover-logo{left:690px;top:245px;width:540px;height:128px;object-position:center}.cover-outro .deck-title{top:444px;text-align:center;font-size:36px;font-weight:400;color:#a8c0ef}.cover-outro .deck-lead{top:520px;text-align:center;font-size:58px;color:#f8fafc}.contact-phone{position:absolute;top:620px;left:192px;width:1536px;text-align:center;font-size:46px;color:#e5edfc}.future-social-space{position:absolute;left:192px;top:765px;width:1536px;height:120px}.cover-outro{background:#070914}.cover-fade{position:absolute;inset:0;background:#0b172b}
'''
 intro_items=[('Qué son y qué no son','robot',3.25),('Elegir el recurso','route',6.05),('Errores y mitos','alert-triangle',7.8),('Buenas prácticas','clipboard-check',8.7)]
 agenda=''.join(f'<article class="deck-card reveal" data-cue="{cue}"><span class="card-icon">{icon(name)}</span><h2>{E(title)}</h2></article>' for title,name,cue in intro_items)
 for ident,kind,content,duration,absolute in [
 ('deck-intro','intro',f'<h1 class="deck-title">Agentes y skills</h1><p class="deck-lead">Bienvenido a tu módulo</p><div class="cover-agenda">{agenda}</div>',intro,0),
 ('deck-outro','outro',f'<h1 class="deck-title">Consultas</h1><p class="deck-lead">{E(config["domain"])}</p><p class="contact-phone">{E(config["phone_display"])}</p><div class="future-social-space" aria-hidden="true"></div>',outro,start)]:
  script=f'''(()=>{{const root=document.getElementById('{ident}'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,tl=gsap.timeline({{paused:true}});root.querySelectorAll('.network-layer').forEach((el,j)=>{{const pose=t=>({{x:reduced?0:Math.sin(({absolute}+t)/21+j*2)*26,y:reduced?0:Math.cos(({absolute}+t)/27+j)*18,rotation:reduced?0:Math.sin(({absolute}+t)/49+j)*1.2}});tl.fromTo(el,pose(0),{{...pose({duration}),duration:{duration},ease:'none'}},0)}});root.querySelectorAll('.light-pulse').forEach(el=>{{const phase=Number(el.dataset.phase);tl.fromTo(el,{{autoRound:false,strokeDashoffset:-phase-(reduced?0:{absolute}/28)}},{{autoRound:false,strokeDashoffset:-phase-(reduced?0:({absolute}+{duration})/28),duration:{duration},ease:'none'}},0)}});root.querySelectorAll('.reveal').forEach(el=>tl.fromTo(el,{{opacity:0,y:reduced?0:20}},{{opacity:1,y:0,duration:.5,ease:'power3.out',immediateRender:false}},Number(el.dataset.cue)));tl.fromTo(root.querySelector('.cover-logo'),{{opacity:0,y:reduced?0:10}},{{opacity:1,y:0,duration:.5,ease:'power3.out'}},.05);'''
  if kind=='outro':script+="tl.to(root.querySelector('.cover-fade'),{opacity:0,duration:1,ease:'power1.inOut'},8);"
  script+=f"window.__timelines['{ident}']=tl;}})();"
  markup=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"></head><body><template><style>{css}{extra}#{ident}{{position:absolute;inset:0;width:100%;height:100%}}</style><div id="{ident}" data-composition-id="{ident}" data-width="1920" data-height="1080" data-duration="{duration}"><section id="frame-{ident}" class="deck-frame cover-{kind} clip" data-start="0" data-duration="{duration}" data-track-index="0"><div class="cover-fade">{network}<img class="cover-logo" src="assets/AS_Horizontal_B.svg" alt="ASmartSolution">{content}</div></section></div><script>{script}</script></template></body></html>'''
  (P/'compositions'/f'{ident}.html').write_text(markup)
 return [dict(id='deck-intro',src='compositions/deck-intro.html',start=0,end=intro,duration=intro,chapter='Bienvenida',title='Agentes y skills',kind='intro',items=[]),dict(id='deck-outro',src='compositions/deck-outro.html',start=start,end=start+outro,duration=outro,chapter='Contacto',title='ASmartSolution · Consultas',kind='outro',items=[])]
